require_once __DIR__ . '/includes/auth.php'; require_staff(); $pdo=db();
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT d.*,r.full_name AS resident_full_name,r.barangay_id,r.address,r.contact_number FROM document_requests d LEFT JOIN residents r ON r.id=d.resident_id WHERE d.id=?');$stmt->execute([$id]);$request=$stmt->fetch();if(!$request){http_response_code(404);exit('Document request not found.');}
